#include "../src/core/manual_alignment.h"
#include "../src/core/rename_pairs.h"
#include "../src/core/crc_profiles.h"
#include "../src/core/log_tail.h"
#include "../src/core/text_report.h"
#include <fstream>
#include <iostream>
#include <algorithm>
using namespace simple_editor::core;
int RunDiscoveryAnalysisTests(const std::filesystem::path& root) {
    int failures = 0; const auto check = [&](bool ok,const wchar_t* text) { std::wcout << (ok ? L"PASS: " : L"FAIL: ") << text << L'\n'; if (!ok) ++failures; }; std::wstring error; std::atomic_bool cancel{false}; LineAnchors anchors;
    check(ParseLineAnchors(L"2,4",&anchors,&error) && anchors[0].first == 1 && anchors[0].second == 3,L"manual line anchors use explicit one-based line numbers"); const std::wstring left = L"head\nitem\nitem\nfooter\n",right = L"head\npadding\nitem\nitem\nfooter\n"; TextMergeModel model;
    check(BuildAnchoredComparison(left,right,{},anchors,cancel,&model,&error),L"manual anchors segment a bounded two-way comparison"); const auto rows = MergeRows(model); check(std::any_of(rows.begin(),rows.end(),[](const auto& row) { return row.left == 1 && row.right == 3; }) && RenderMerge(model) == left,L"forced line pairing retains exact original source/output bytes");
    check(!ParseLineAnchors(L"3,2\n2,3",&anchors,&error) && !ParseLineAnchors(L"0,1",&anchors,&error),L"crossing and zero manual line anchors are rejected"); ParseLineAnchors(L"100,100",&anchors,&error); check(!BuildAnchoredComparison(left,right,{},anchors,cancel,&model,&error) && RenderMerge(model) == left,L"out-of-file anchors preserve the previous adopted model");
    const auto write = [](const std::filesystem::path& path,const std::string& bytes) { std::filesystem::create_directories(path.parent_path()); std::ofstream file(path,std::ios::binary); file.write(bytes.data(),bytes.size()); }; const auto a = root / L"pair-left",b = root / L"pair-right"; write(a / L"old.bin","abc"); write(b / L"new.bin","abc"); write(a / L"sub/one.bin","xyz"); write(b / L"other/two.bin","xyz"); write(a / L"dup1.bin","dup"); write(a / L"dup2.bin","dup"); write(b / L"dup3.bin","dup"); write(b / L"dup4.bin","dup"); FolderScan scan; std::vector<ContentPair> pairs;
    check(ScanFolders(a,b,{},cancel,[](unsigned) {},&scan,&error) && FindContentPairs(scan,{},&pairs,&error) && pairs.size() == 3,L"content pairing finds renamed and moved files without changing scan rows"); check(std::count_if(pairs.begin(),pairs.end(),[](const auto& pair) { return pair.left_count == 1 && pair.right_count == 1 && !pair.left.empty() && !pair.right.empty(); }) == 2 && std::any_of(pairs.begin(),pairs.end(),[](const auto& pair) { return pair.state == L"Ambiguous duplicate content" && pair.left.empty() && pair.right.empty(); }),L"duplicate content is reported as an ambiguous group without choosing a pairing");
    SaveControl control; control.cancelled = &cancel; control.progress = [&](unsigned) { cancel = true; }; const auto old_pairs = pairs.size(); check(!FindContentPairs(scan,control,&pairs,&error) && pairs.size() == old_pairs,L"cancelled content hashing preserves prior pairing results"); cancel = false; write(a / L"old.bin","changed-size"); check(!FindContentPairs(scan,{},&pairs,&error),L"content pairing rejects candidates changed since the folder scan");
    const auto crc_path = root / L"crc-vector.bin"; write(crc_path,"XX123456789YY"); BinaryDocument document; document.Open(crc_path.wstring(),&error); const std::pair<const wchar_t*,std::uint64_t> vectors[] = {{L"CRC-16/ARC",0xBB3D},{L"CRC-16/MODBUS",0x4B37},{L"CRC-32/ISO-HDLC",0xCBF43926},{L"CRC-32/ISCSI",0xE3069283},{L"CRC-64/ECMA-182",0x6C40DF5F0B497347}};
    for (const auto& vector : vectors) { CrcProfile profile; std::uint64_t value = 0; const bool good = ParseCrcProfile(L"preset=" + std::wstring(vector.first),&profile,&error) && CalculateCrc(document,2,9,profile,{},&value,&error) && value == vector.second; check(good,(L"known CRC check vector: " + std::wstring(vector.first)).c_str()); }
    CrcProfile custom; std::uint64_t value = 0; check(ParseCrcProfile(L"name=CAN-FD check\nwidth=17\npolynomial=1685B\ninit=0\nxorout=0\nrefin=no\nrefout=no",&custom,&error) && CalculateCrc(document,2,9,custom,{},&value,&error) && value == 0x4F03,L"custom non-byte-width CRC parameters follow the catalogue convention"); check(!ParseCrcProfile(L"width=7",&custom,&error) && !ParseCrcProfile(L"width=16\npolynomial=10000",&custom,&error) && !ParseCrcProfile(L"execute=shell",&custom,&error),L"CRC widths, polynomial bounds and unknown commands are rejected");
    custom = {}; value = 123; cancel = true; control.progress = {}; check(!CalculateCrc(document,2,9,custom,control,&value,&error) && value == 123 && !document.IsModified(),L"cancelled custom CRC leaves the result and input untouched"); cancel = false; check(CalculateCrc(document,0,0,custom,{},&value,&error) && value == 0,L"empty CRC-32/ISO-HDLC range returns its defined check value");
    const auto log = root / L"tail.log"; write(log,"first\n"); LogTailResult tail; check(ReadLogTail(log,TextEncoding::Utf8,{}, {},&tail,&error) && tail.changed && tail.page.text == L"first\n",L"read-only log tail reads a bounded disk window"); const auto initial = tail.stamp; { std::ofstream append(log,std::ios::binary | std::ios::app); append << "next\n"; } check(ReadLogTail(log,TextEncoding::Utf8,initial,{},&tail,&error) && tail.changed && tail.page.text.find(L"next") != std::wstring::npos,L"log tail follows appended saved content"); auto previous_tail = tail.stamp; write(log,"x\n"); check(ReadLogTail(log,TextEncoding::Utf8,previous_tail,{},&tail,&error) && tail.state.find(L"truncated") != std::wstring::npos,L"log truncation is identified explicitly"); previous_tail = tail.stamp; const auto old_log = root / L"rotated.log"; MoveFileW(log.c_str(),old_log.c_str()); write(log,"rotated\n"); check(ReadLogTail(log,TextEncoding::Utf8,previous_tail,{},&tail,&error) && tail.state.find(L"rotated") != std::wstring::npos && tail.page.text == L"rotated\n",L"log rotation follows the new path identity without altering an editor"); previous_tail = tail.stamp; check(ReadLogTail(log,TextEncoding::Utf8,previous_tail,{},&tail,&error) && !tail.changed,L"unchanged log polling avoids replacing its native view"); check(!ReadLogTail(log,TextEncoding::Big5,{}, {},&tail,&error),L"ambiguous legacy-code-page tail offsets are refused");
    LineOptions filtered; ParseTextRules(L"mask-timestamps=yes",&filtered.rules,&error); TextReportStats stats; const auto report = root / L"ignored-summary.txt"; check(ExportTextReport(L"2026-01-01 00:00:00 value\n",L"2026-02-01 12:00:00 value\n",{},report,TextReportFormat::Summary,{},&stats,&error,false,&filtered,L"mask-timestamps=yes") && stats.blocks == 0 && stats.ignored == 1,L"text reports retain active comparison rules and explicit ignored-block counts");
    return failures;
}
